-- ═══ Bridge — Q4 2026 OKR tree (BloomingBox_Q4_OKR_Tree_Bridge.xlsx, 12 Oct 2026) ═══
-- REPLACES the 2 Oct "Road to 1,000" seed (okr_r1k_*): those 63 rows are SOFT-deleted (Bridge's own deleted_at), not removed.
-- Rollback: supabase/seed/2026-10-12_q4_okr_tree_ROLLBACK.sql restores them and removes everything this file adds/changes.
-- Idempotent: fixed ids (okr_q4_*) with ON CONFLICT DO NOTHING; the field changes are plain updates.
-- Decisions (Kartik, 12 Oct): 'Leadership (assign CEO user)' → Owner to be decided; the 42 'Existing to weekly' rows are
-- left as they are (their Q4 children already have a weekly check-in); 'Pricing +2%' and 'Virtual Data Room' untouched.
-- 'Proposed - owner to confirm' numbers land with target_confirmed=false + a needs-decision note.

-- 0. full snapshot of the OKR table before anything changes
create table if not exists public.okrs_backup_2026_10_12 as select * from public.okrs;

-- 1. retire the 2 Oct seed (soft delete — restorable)
update public.okrs set deleted_at = now(), deleted_by = 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', updated_at = now()
 where id like 'okr_r1k_%' and deleted_at is null;

-- 2. the Q4 tree (72 rows)
on conflict (id) do nothing;

select 'okl_q4_'||o.id, o.id, 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', 'Created objective', jsonb_build_object('source','Q4 2026 OKR tree sheet (12 Oct 2026)'), now()
from public.okrs o where o.id like 'okr_q4_%' and not exists (select 1 from public.okr_logs l where l.id='okl_q4_'||o.id);

-- 3. changes to existing rows (sheet 2)
update public.okrs set owner_id = null, owners = '[]'::jsonb, owner_tbd = true, needs_decision = true,
  decision_note = coalesce(nullif(decision_note,''),'') || 'Owner: leadership (CEO) to assign — profitability and funding outcomes are cross-functional.',
  description = 'Growth is tracked in daily orders first; revenue follows. Price is not a lever for this target.', updated_at = now()
 where id = 'okr_fqqr7zd';   -- Drive revenue growth …
update public.okrs set target_value = 34000000, updated_at = now() where id = 'okr_nwrkvpl';   -- B2C Growth: AED 27M → AED 34M (target was 32M)
update public.okrs set owner_id = null, owners = '[]'::jsonb, owner_tbd = true, needs_decision = true,
  decision_note = coalesce(nullif(decision_note,''),'') || 'Owner: leadership (CEO) to assign — every department contributes to profit; Derick keeps Gross Profit 40% → 43%.', updated_at = now()
 where id = 'okr_ne2obtf';   -- Double Net Profit Margin from 4% to 8%
update public.okrs set description = 'Extension of the UAE structure, not a separate bet - mirrored once the UAE tree is final.', updated_at = now()
 where id = 'okr_kcwlg0a';   -- Capture market share and increase revenue in KSA

-- sanity
select (select count(*) from public.okrs where id like 'okr_q4_%' and deleted_at is null) as q4_rows,
       (select count(*) from public.okrs where id like 'okr_r1k_%' and deleted_at is null) as r1k_still_live;
